            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">THE BUILDER AND THE NAIL</text><text x=\"550\" y=\"100\" text-anchor=\"middle\" fill=\"#888\" font-size=\"23\">BMJ case report, 1995</text><rect x=\"80\" y=\"170\" width=\"440\" height=\"300\" rx=\"20\" fill=\"rgba(239,68,68,0.1)\" stroke=\"#ef4444\" stroke-width=\"2\"/><text x=\"300\" y=\"230\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"24\">WHAT HE FELT</text><text x=\"300\" y=\"290\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Severe, sharp pain</text><text x=\"300\" y=\"330\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Needed strong sedation</text><text x=\"300\" y=\"370\" text-anchor=\"middle\" fill=\"#888\" font-size=\"16\">Every movement made it worse</text><rect x=\"580\" y=\"170\" width=\"440\" height=\"300\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"800\" y=\"230\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"24\">WHAT WAS THERE</text><text x=\"800\" y=\"290\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Nail between the toes</text><text x=\"800\" y=\"330\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Zero tissue injury</text><text x=\"800\" y=\"370\" text-anchor=\"middle\" fill=\"#888\" font-size=\"16\">Foot completely unharmed</text><rect x=\"150\" y=\"560\" width=\"800\" height=\"120\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"612\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"24\">Pain measured THREAT,</text><text x=\"550\" y=\"652\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"24\">not damage</text></svg>",
