            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">KNOWLEDGE CHECK</text><rect x=\"150\" y=\"120\" width=\"800\" height=\"180\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"180\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"22\">STIFF, PAINFUL SHOULDER</text><text x=\"550\" y=\"225\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"18\">Age 52, diabetes, no injury</text><text x=\"550\" y=\"260\" text-anchor=\"middle\" fill=\"#888\" font-size=\"16\">Worse at night, stiffer each month</text><circle cx=\"250\" cy=\"560\" r=\"100\" fill=\"rgba(239,68,68,0.2)\" stroke=\"#ef4444\" stroke-width=\"2\"/><text x=\"250\" y=\"568\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"18\">Freezing</text><circle cx=\"550\" cy=\"560\" r=\"100\" fill=\"rgba(59,130,246,0.2)\" stroke=\"#3b82f6\" stroke-width=\"2\"/><text x=\"550\" y=\"568\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"18\">Frozen</text><circle cx=\"850\" cy=\"560\" r=\"100\" fill=\"rgba(16,185,129,0.2)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"850\" y=\"568\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"18\">Thawing</text></svg>",
